using System.Text.Json.Nodes;
using Demo;
using Xunit;
public class WorkflowTests {
 static JsonObject P(string s)=>JsonNode.Parse(s)!.AsObject();
 [Fact]public void ReserveReplayCannotDoubleSpend(){var e=new Engine();var p=P("""{"id":"a","sku":"BOOK","quantity":2,"version":0}""");e.Command("reserve",p,"learner");e.Command("reserve",p,"learner");Assert.Equal(8,e.State()["stock"]!.GetValue<int>());p["quantity"]=3;Assert.Equal(409,Assert.Throws<Problem>(()=>e.Command("reserve",p,"learner")).Status);}
 [Fact]public async Task ParallelReservationsCannotOversell(){var e=new Engine();var outcomes=await Task.WhenAll(Enumerable.Range(0,10).Select(i=>Task.Run(()=>{try{e.Command("reserve",new(){["id"]=i.ToString(),["sku"]="BOOK",["quantity"]=8,["version"]=0},"learner");return 200;}catch(Problem p){return p.Status;}})));Assert.Single(outcomes,s=>s==200);Assert.Equal(2,e.State()["stock"]!.GetValue<int>());}
 [Fact]public void OutboxOutageRetainsMessages(){var e=new Engine();e.Command("reserve",P("""{"id":"a","sku":"BOOK","quantity":1,"version":0}"""),"learner");Assert.Throws<Problem>(()=>e.Command("relay",new(){["simulateFailure"]=true},"operator"));Assert.Single(e.Command("relay",new(),"operator")["delivered"]!.AsArray());Assert.Empty(e.Command("relay",new(),"operator")["delivered"]!.AsArray());}
 [Fact]public void InstructorReviewCannotAlterDeterministicScore(){var e=new Engine();e.Command("submit",P("""{"id":"s","student":"S","answers":["transaction","wrong","audit"],"deadline":2000000000}"""),"learner");Assert.Equal(403,Assert.Throws<Problem>(()=>e.Command("feedback",P("""{"id":"s","version":0,"feedback":"Review rubric"}"""),"learner")).Status);e.Command("feedback",P("""{"id":"s","version":0,"feedback":"Review rubric"}"""),"instructor");Assert.Equal(409,Assert.Throws<Problem>(()=>e.Command("publish",P("""{"id":"s","version":0}"""),"instructor")).Status);Assert.Equal(2,e.Command("publish",P("""{"id":"s","version":1}"""),"instructor")["score"]!.GetValue<int>());}
 [Fact]public void IngestionValidatesBeforeCreatingRetryableRecord(){var e=new Engine();Assert.Throws<Problem>(()=>e.Command("ingest",P("""{"id":"f","rows":[{"sku":"BOOK","quantity":-1}]}"""),"operator"));Assert.Empty(e.State()["files"]!.AsArray());var p=P("""{"id":"f","rows":[{"sku":"BOOK","quantity":1}]}""");e.Command("ingest",p,"operator");e.Command("ingest",p,"operator");Assert.Equal("retry",e.Command("replay",P("""{"id":"f","simulateFailure":true}"""),"operator")["status"]!.GetValue<string>());Assert.Equal("processed",e.Command("replay",P("""{"id":"f"}"""),"operator")["status"]!.GetValue<string>());Assert.Single(e.State()["files"]!.AsArray());}
}
